package com.tiny.snake; import android.app.Activity; import android.content.Context; import android.graphics.*; import android.os.*; import android.view.*; import java.util.Random; public class MainActivity extends Activity { @Override protected void onCreate(Bundle b) { super.onCreate(b); requestWindowFeature(1); getWindow().setFlags(1024, 1024); setContentView(new SnakeView(this)); } private class SnakeView extends View { int[] x = new int[300], y = new int[300]; int len = 3, dx = 1, dy = 0, fx, fy, cols = 15, rows = 15; Paint p = new Paint(); Handler h = new Handler(); Random r = new Random(); float sx, sy; public SnakeView(Context c) { super(c); reset(); h.postDelayed(new Runnable() { public void run() { update(); invalidate(); h.postDelayed(this, 150); } }, 150); } void reset() { len = 3; dx = 1; dy = 0; for (int i = 0; i < len; i++) { x[i] = 5 - i; y[i] = 5; } spawn(); } void spawn() { fx = r.nextInt(cols); fy = r.nextInt(rows); } void update() { for (int i = len - 1; i > 0; i--) { x[i] = x[i - 1]; y[i] = y[i - 1]; } x[0] += dx; y[0] += dy; if (x[0] < 0 || x[0] >= cols || y[0] < 0 || y[0] >= rows) { reset(); return; } for (int i = 1; i < len; i++) if (x[0] == x[i] && y[0] == y[i]) { reset(); return; } if (x[0] == fx && y[0] == fy) { len++; spawn(); } } @Override protected void onDraw(Canvas c) { c.drawColor(-16777216); int w = getWidth(), h = getHeight(); if (w == 0) return; int ts = w / cols; rows = h / ts; p.setColor(-65536); c.drawRect(fx * ts, fy * ts, (fx + 1) * ts, (fy + 1) * ts, p); p.setColor(-16711936); for (int i = 0; i < len; i++) c.drawRect(x[i] * ts, y[i] * ts, (x[i] + 1) * ts, (y[i] + 1) * ts, p); } @Override public boolean onTouchEvent(MotionEvent e) { if (e.getAction() == 0) { sx = e.getX(); sy = e.getY(); } else if (e.getAction() == 1) { float ex = e.getX() - sx, ey = e.getY() - sy; if (Math.abs(ex) > Math.abs(ey)) { if (ex > 30 && dx == 0) { dx = 1; dy = 0; } else if (ex < -30 && dx == 0) { dx = -1; dy = 0; } } else { if (ey > 30 && dy == 0) { dx = 0; dy = 1; } else if (ey < -30 && dy == 0) { dx = 0; dy = -1; } } } return true; } } }
  
